SELECT DISTINCT md.chembl_id AS compound_chembl_id, cs.canonical_smiles FROM target_dictionary td JOIN assays a ON a.tid = td.tid JOIN activities act ON act.assay_id = a.assay_id JOIN molecule_dictionary md ON md.molregno = act.molregno JOIN compound_structures cs ON cs.molregno = md.molregno WHERE td.chembl_id = 'CHEMBL203' AND a.assay_organism = 'Homo sapiens' ORDER BY compound_chembl_id, canonical_smiles
